public class DamageTakenDotEffect : DoTEffect
{
	private static string dotStr = "damageTakenDotEffect";

	private Health parentHealth;

	private NumVarStatMod damageMod;

	public DamageTakenDotEffect(Entity givenEntity, float givenMultiplier, float givenDuration)
		: base(string.Empty, string.Empty, 0, givenEntity, null)
	{
		if (!(givenEntity == null))
		{
			ID = dotStr;
			useInterval = false;
			damageInterval = givenDuration;
			damageStopwatchID = ChaosStopwatch.Begin(damageInterval);
			parentHealth = givenEntity.health;
			damageMod = new NumVarStatMod(ID, givenMultiplier, 10, VarStatModType.Multiplicative);
		}
	}

	public override bool Update()
	{
		if (parentEntity == null || parentHealth == null || parentHealth.healthStat.CurrentValue <= 0f || ChaosStopwatch.Check(damageStopwatchID))
		{
			CleanUp();
			ToggleMods(givenStatus: false);
			return true;
		}
		return false;
	}

	public override void Init()
	{
		ToggleMods(givenStatus: true);
	}

	private void ToggleMods(bool givenStatus)
	{
		if (parentHealth != null)
		{
			parentHealth.damageTakenStat.Modify(damageMod, givenStatus);
		}
	}
}
