public class BabylonScalesDotEffect : SlowDotEffect
{
	public BabylonScalesDotEffect(Entity newEnt, float newDuration, float newValue, bool newStatus)
		: base(string.Empty, 0, newEnt, null)
	{
		useInterval = false;
		damageInterval = newDuration;
		damageStopwatchID = ChaosStopwatch.Begin(damageInterval);
		isBuff = newStatus;
		modIDString = Player.UseBabylonScales.staticID;
		slowValue = ((!isBuff) ? newValue : (0f - newValue));
		slowMod = new NumVarStatMod(modIDString, 0f - slowValue, 7, VarStatModType.LateMultiplicative);
	}

	public override void SetSlowValues(int givenLevel)
	{
		slowMod = new NumVarStatMod(modIDString, 0f - slowValue, 7, VarStatModType.LateMultiplicative);
	}

	public override void CreateEffectObject()
	{
		effectObject = Globals.ChaosInst<BaseEffect>(BabylonScalesEffect.Prefab, parentEntity.transform.parent, parentEntity.hurtBoxTransform.position);
		effectObject.entity = parentEntity;
		(effectObject as BabylonScalesEffect).isBuff = isBuff;
		PlayAudio();
	}

	public override void ToggleMovementMods(bool status)
	{
		if (!(parentEntity == null) && !(parentEntity.movement == null))
		{
			parentEntity.movement.moveSpeedStat.Modify(slowMod, status);
			if (!isBuff)
			{
				parentEntity.movement.dashSpeedStat.Modify(slowMod, status);
			}
		}
	}

	public override void PlayAudio()
	{
		if (isBuff)
		{
			SoundManager.PlayAudioWithDistance("WindArrowEnd", parentEntity.transform.position);
		}
		else
		{
			base.PlayAudio();
		}
	}
